def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 8:
            rich_opp += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif hp <= 4 or no_water_days >= 1:
        if supply_tight:
            bid = max(DAILY_SALARY * 0.82, highest_prev + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.68, avg_prev + 2.0)
    else:
        if supply_loose:
            bid = max(DAILY_SALARY * 0.28, avg_prev * 0.75)
        elif supply_tight:
            bid = max(DAILY_SALARY * 0.52, avg_prev + 1.0)
        else:
            bid = max(DAILY_SALARY * 0.4, avg_prev * 0.9)

    if urgent_opp >= 2:
        bid += 6.0
    elif urgent_opp == 1:
        bid += 3.0

    if rich_opp >= 1 and highest_prev >= DAILY_SALARY * 0.9:
        if hp > 4 and no_water_days == 0:
            bid *= 0.72
        else:
            bid = max(bid, DAILY_SALARY * 0.88)

    if day >= 8:
        bid += 4.0
    if day == 10:
        bid += 6.0

    reserve_floor = 0.0
    if hp > 4 and no_water_days == 0:
        reserve_floor = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve_floor = DAILY_SALARY * 0.6

    max_affordable = max(0.0, budget - reserve_floor)
    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable if max_affordable > 0 else budget)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid_amount = 0.0

    if my_status['hp'] <= 2:
        bid_amount = DAILY_SALARY * 0.95
    elif my_status['hp'] == 3:
        bid_amount = DAILY_SALARY * 0.85
    else:
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid >= DAILY_SALARY * 0.7:
                bid_amount = highest_prev_bid + 1.0
            else:
                bid_amount = max(DAILY_SALARY * 0.5, highest_prev_bid + 5.0)
        else:
            bid_amount = DAILY_SALARY * 0.55

    final_bid = max(1.0, min(my_status['budget'], bid_amount))

    return final_bid

